from scipy.optimize import curve_fit
m=A<0.4
tt=t[m]; yy=dA_dt[m]
forms={
'exp':(lambda t,a,b,c: a-b*np.exp(-c*t),[6.5,4,0.5]),
'hill':(lambda t,V,K,p: V*t**p/(K**p+t**p),[6.5,1,1]),
'log':(lambda t,a,b: a+b*np.log(t),[3,2]),
'pow':(lambda t,a,p: a*t**p,[3,0.3]),
}
